mapper.select:
SELECT w.id, w.customer_name AS customer, w.package_desc AS pkgDesc, w.type AS type, c.name AS community, w.address, w.time_slot AS timeSlot, COALESCE(k.name, '—') AS worker, w.status, w.cluster_id AS clusterId, w.adjacent_route AS adjacent FROM work_order w LEFT JOIN community c ON c.id = w.community_id LEFT JOIN worker k ON k.id = w.worker_id WHERE 1 = 1
AND w.dept_id IN #{d}
AND w.status = #{status}
AND (w.id LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%') OR w.customer_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY w.time_slot, w.id
